cat << 'EOF' > /app/probe_adapters.py
import json
import subprocess

test_cases = {
    'space': '  a/b  ',
    'pct': 'a%2fb',
    'pct2': 'a%252fb',
    'bs': 'a\\b',
    'nfkc': 'a\uff0fb'
}

base_requests = {
    'json': {'method': 'POST', 'target': '/v1/render', 'headers': [['Content-Type', 'application/json']], 'body': {}},
    'query': {'method': 'POST', 'target': '/v1/render', 'headers': [], 'body': ''},
    'form': {'method': 'POST', 'target': '/v1/render', 'headers': [['Content-Type', 'application/x-www-form-urlencoded']], 'body': ''},
    'header': {'method': 'POST', 'target': '/v1/render', 'headers': [['X-Integration-Mode', 'legacy']], 'body': ''}
}

results = {c: {} for c in base_requests}

for carrier, req in base_requests.items():
    for t_name, t_val in test_cases.items():
        r = json.loads(json.dumps(req))
        if carrier == 'json':
            r['body'] = json.dumps({'template': t_val})
        elif carrier == 'query':
            import urllib.parse
            r['target'] = f'/v1/render?template={urllib.parse.quote(t_val)}'
        elif carrier == 'form':
            import urllib.parse
            r['body'] = f'template={urllib.parse.quote(t_val)}'
        elif carrier == 'header':
            r['headers'].append(['X-Legacy-Template', t_val])

        with open('/tmp/test.json', 'w') as f:
            json.dump(r, f)

        out = subprocess.check_output(['/app/waflab', 'inspect', '/tmp/test.json'])
        out_data = json.loads(out)
        # find the locator
        locs = out_data.get('locators', [])
        if locs:
            results[carrier][t_name] = locs[0]['normalized']
        else:
            results[carrier][t_name] = 'NOT_FOUND'

print(json.dumps(results, indent=2))
EOF
python3 /app/probe_adapters.py

